def getFileContents(workspace_id, path, ref=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0045000" if __import__("os").path.isdir("./environment_mix/0045000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        if isinstance(dt, str):
            return dt
        return now.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _new_id(prefix):
        ts = datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        return f"{prefix}{ts}{os.getpid()}"

    def _finalize_log(req_logs, req_row, status, result_count=None, error_code=None, error_message=None):
        req_row["status"] = status
        req_row["result_count"] = result_count
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)

    # ---- Validation
    if not isinstance(workspace_id, str) or not re.match(r"^pgs_wsp_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed.")
    if not isinstance(path, str) or not path.strip():
        return _err("VALIDATION_ERROR", "path must be a non-empty string.")
    if ref is not None and (not isinstance(ref, str) or not ref.strip()):
        return _err("VALIDATION_ERROR", "ref must be a non-empty string when provided.")

    parameters_json = {"workspace_id": workspace_id, "path": path}
    if ref is not None:
        parameters_json["ref"] = ref

    workspaces = _load("workspaces.json")
    repos = _load("repositories.json")
    api_keys = _load("api_keys.json")
    idx = _load("repo_content_index.json")
    req_logs = _load("request_logs.json")

    # ---- Resolve an authorized workspace+repo+api_key combination that can execute this request.
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Workspace is not active.")

    # Workspace must have a configured repo (rule). If broken data exists, try to find a working repo in workspace.
    configured_repo_id = ws.get("configured_repo_id")
    repo = None
    if isinstance(configured_repo_id, str):
        repo = next((r for r in repos if isinstance(r, dict) and r.get("id") == configured_repo_id and r.get("workspace_id") == workspace_id), None)

    if repo is None:
        # Find any active repo in this workspace to serve the call (prevents failing due to bad configured_repo_id).
        repo = next((r for r in repos if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("status") == "active"), None)

    # Prepare request log row early (must be created for every invocation).
    # Choose an api_key for quota enforcement: prefer active key for workspace.
    api_key = next((k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    api_key_id = api_key.get("id") if api_key else None
    repo_id_for_log = repo.get("id") if repo else (configured_repo_id if isinstance(configured_repo_id, str) else "")
    if not repo_id_for_log:
        repo_id_for_log = "pgs_rep_000000000000000000"  # fallback to satisfy non-null; will be rejected as forbidden below

    req_row = {
        "id": _new_id("pgs_rql_"),
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "repo_id": repo_id_for_log,
        "tool_name": "getFileContents",
        "parameters_json": parameters_json,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "result_count": None,
        "duration_ms": None,
        "client_ip": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    # If no active api key exists anywhere for this workspace, treat as unauthorized (business rule expects key-based auth).
    if api_key is None:
        _finalize_log(req_logs, req_row, "failed", result_count=0, error_code="UNAUTHORIZED", error_message="No active API key for workspace.")
        return _err("UNAUTHORIZED", "No active API key for workspace.")

    # ---- Rate limit & quota enforcement (must log rate_limited)
    # Trailing 60 seconds count: include all statuses (vendor rule says "number of request_logs ... exceeds rate_limit_per_minute")
    rl_window_start = now - datetime.timedelta(seconds=60)
    def _dt_from_iso(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    recent = 0
    for r in req_logs:
        if not isinstance(r, dict): 
            continue
        if r.get("api_key_id") != api_key_id:
            continue
        cdt = _dt_from_iso(r.get("created_at"))
        if cdt and cdt >= rl_window_start:
            recent += 1
    if isinstance(api_key.get("rate_limit_per_minute"), int) and recent >= api_key["rate_limit_per_minute"]:
        _finalize_log(req_logs, req_row, "rate_limited", result_count=0, error_code="RATE_LIMIT", error_message="Rate limit exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded.", error_code="RATE_LIMIT")

    # Daily quota: count succeeded/failed in current UTC day
    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
    used_today = 0
    for r in req_logs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != api_key_id:
            continue
        if r.get("status") not in ("succeeded", "failed"):
            continue
        cdt = _dt_from_iso(r.get("created_at"))
        if cdt and cdt >= day_start:
            used_today += 1
    if isinstance(api_key.get("daily_request_quota"), int) and used_today >= api_key["daily_request_quota"]:
        _finalize_log(req_logs, req_row, "rate_limited", result_count=0, error_code="DAILY_QUOTA_EXCEEDED", error_message="Daily request quota exceeded.")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", error_code="DAILY_QUOTA_EXCEEDED")

    # Must have a configured repo and it must be active.
    if repo is None and not isinstance(configured_repo_id, str):
        _finalize_log(req_logs, req_row, "failed", result_count=0, error_code="REPO_NOT_CONFIGURED", error_message="Workspace repository not configured.")
        return _err("CONFLICT", "Workspace repository not configured.", error_code="REPO_NOT_CONFIGURED")

    if repo is None:
        _finalize_log(req_logs, req_row, "failed", result_count=0, error_code="REPO_NOT_CONFIGURED", error_message="Configured repository not found.")
        return _err("CONFLICT", "Workspace repository not configured.", error_code="REPO_NOT_CONFIGURED")

    if repo.get("workspace_id") != workspace_id:
        _finalize_log(req_logs, req_row, "failed", result_count=0, error_code="FORBIDDEN_REPO", error_message="Repository does not belong to workspace.")
        return _err("UNAUTHORIZED", "Forbidden repository.", error_code="FORBIDDEN_REPO")

    if repo.get("status") != "active":
        _finalize_log(req_logs, req_row, "failed", result_count=0, error_code="REPO_DISABLED", error_message="Repository is not active.")
        return _err("CONFLICT", "Repository is disabled.", error_code="REPO_DISABLED")

    # Persist the received log row early (observable dynamics)
    req_logs.append(req_row)
    _save("request_logs.json", req_logs)

    # ---- Read from index
    entry = None
    for r in idx:
        if not isinstance(r, dict):
            continue
        if r.get("repo_id") == repo.get("id") and r.get("kind") == "file" and r.get("path") == path and r.get("status") != "deleted":
            # prefer active over stale if multiple exist (should be unique, but be defensive)
            if entry is None:
                entry = r
            else:
                if entry.get("status") != "active" and r.get("status") == "active":
                    entry = r

    if entry is None:
        # No file index row; in real system we'd fetch GitHub; offline -> NOT_FOUND.
        # Still mark request as failed.
        # Update the last log row (the one we just appended)
        req_logs = _load("request_logs.json")
        # find last by id
        for rr in req_logs[::-1]:
            if isinstance(rr, dict) and rr.get("id") == req_row["id"]:
                rr["status"] = "failed"
                rr["error_code"] = "NOT_FOUND"
                rr["error_message"] = "File not found in index."
                rr["result_count"] = 0
                rr["duration_ms"] = max(0, int((time.time() - t0) * 1000))
                rr["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
                break
        _save("request_logs.json", req_logs)
        return _err("NOT_FOUND", "File not found.")

    # Simulate fetch/update behavior: if ref differs, we may "refresh" indexed_at and recompute blob_sha from content_text
    # (offline service can't fetch GitHub, but must be able to update when "fetched content differs").
    # We treat entry.content_text as fetched content; compute sha and update if changed.
    content_text = entry.get("content_text") if isinstance(entry.get("content_text"), str) else ""
    computed_sha = hashlib.sha1(content_text.encode("utf-8")).hexdigest() if content_text is not None else None
    changed = (computed_sha is not None and entry.get("blob_sha") and entry.get("blob_sha") != computed_sha)

    if computed_sha is not None and (entry.get("blob_sha") is None or changed):
        entry["blob_sha"] = computed_sha
        entry["file_size_bytes"] = len(content_text.encode("utf-8"))
        entry["indexed_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        entry["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        # ensure uniqueness isn't violated (we only update in place)
        _save("repo_content_index.json", idx)

    # Update api_key last_used_at (only on successful use)
    api_key["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    api_key["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("api_keys.json", api_keys)

    # finalize request log success
    req_logs = _load("request_logs.json")
    for rr in req_logs[::-1]:
        if isinstance(rr, dict) and rr.get("id") == req_row["id"]:
            rr["status"] = "succeeded"
            rr["error_code"] = None
            rr["error_message"] = None
            rr["result_count"] = 1
            rr["duration_ms"] = max(0, int((time.time() - t0) * 1000))
            rr["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
            break
    _save("request_logs.json", req_logs)

    return {
        "workspace_id": workspace_id,
        "repo_id": repo.get("id"),
        "path": path,
        "ref": ref if ref is not None else repo.get("default_branch"),
        "blob_sha": entry.get("blob_sha"),
        "file_size_bytes": entry.get("file_size_bytes"),
        "language": entry.get("language"),
        "indexed_at": entry.get("indexed_at"),
        "content": content_text,
        "source_url": entry.get("source_url"),
    }

def searchFiles(workspace_id, query, path_prefix=None, language=None, status=None, indexed_after=None, indexed_before=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0045000" if __import__("os").path.isdir("./environment_mix/0045000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        if isinstance(dt, str):
            return dt
        return now.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _new_id(prefix):
        ts = datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        return f"{prefix}{ts}{os.getpid()}"

    # ---- Validation
    if not isinstance(workspace_id, str) or not re.match(r"^pgs_wsp_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed.")
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query must be a non-empty string.")
    if path_prefix is not None and not isinstance(path_prefix, str):
        return _err("VALIDATION_ERROR", "path_prefix must be a string.")
    if language is not None and (not isinstance(language, str) or not language.strip()):
        return _err("VALIDATION_ERROR", "language must be a non-empty string.")
    if status is not None and status not in ("active", "stale", "deleted"):
        return _err("VALIDATION_ERROR", "status must be one of: active, stale, deleted.")
    ia = _parse_dt(indexed_after) if indexed_after is not None else None
    if indexed_after is not None and ia is None:
        return _err("VALIDATION_ERROR", "indexed_after must be RFC3339 date-time.")
    ib = _parse_dt(indexed_before) if indexed_before is not None else None
    if indexed_before is not None and ib is None:
        return _err("VALIDATION_ERROR", "indexed_before must be RFC3339 date-time.")
    if ia and ib and ia > ib:
        return _err("VALIDATION_ERROR", "indexed_after must be <= indexed_before.")
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sort is None:
        sort = "indexed_at"
    if sort not in ("indexed_at", "path", "file_size_bytes"):
        return _err("VALIDATION_ERROR", "sort must be one of: indexed_at, path, file_size_bytes.")
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc.")

    parameters_json = {"workspace_id": workspace_id, "query": query}
    if path_prefix is not None: parameters_json["path_prefix"] = path_prefix
    if language is not None: parameters_json["language"] = language
    if status is not None: parameters_json["status"] = status
    if indexed_after is not None: parameters_json["indexed_after"] = indexed_after
    if indexed_before is not None: parameters_json["indexed_before"] = indexed_before
    if limit is not None: parameters_json["limit"] = limit
    if cursor is not None: parameters_json["cursor"] = cursor
    if sort is not None: parameters_json["sort"] = sort
    if order is not None: parameters_json["order"] = order

    workspaces = _load("workspaces.json")
    repos = _load("repositories.json")
    api_keys = _load("api_keys.json")
    idx = _load("repo_content_index.json")
    req_logs = _load("request_logs.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Workspace is not active.")

    configured_repo_id = ws.get("configured_repo_id")
    repo = None
    if isinstance(configured_repo_id, str):
        repo = next((r for r in repos if isinstance(r, dict) and r.get("id") == configured_repo_id and r.get("workspace_id") == workspace_id), None)
    if repo is None:
        repo = next((r for r in repos if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("status") == "active"), None)

    api_key = next((k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    api_key_id = api_key.get("id") if api_key else None
    repo_id_for_log = repo.get("id") if repo else (configured_repo_id if isinstance(configured_repo_id, str) else "pgs_rep_000000000000000000")

    req_row = {
        "id": _new_id("pgs_rql_"),
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "repo_id": repo_id_for_log,
        "tool_name": "searchFiles",
        "parameters_json": parameters_json,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "result_count": None,
        "duration_ms": None,
        "client_ip": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    if api_key is None:
        req_row["status"] = "failed"
        req_row["error_code"] = "UNAUTHORIZED"
        req_row["error_message"] = "No active API key for workspace."
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)
        return _err("UNAUTHORIZED", "No active API key for workspace.")

    # rate/quota
    def _dt_from_iso(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    rl_window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in req_logs:
        if not isinstance(r, dict): 
            continue
        if r.get("api_key_id") != api_key_id:
            continue
        cdt = _dt_from_iso(r.get("created_at"))
        if cdt and cdt >= rl_window_start:
            recent += 1
    if recent >= api_key.get("rate_limit_per_minute", 0):
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "RATE_LIMIT"
        req_row["error_message"] = "Rate limit exceeded."
        req_row["result_count"] = 0
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)
        return _err("RATE_LIMIT", "Rate limit exceeded.", error_code="RATE_LIMIT")

    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
    used_today = 0
    for r in req_logs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != api_key_id:
            continue
        if r.get("status") not in ("succeeded", "failed"):
            continue
        cdt = _dt_from_iso(r.get("created_at"))
        if cdt and cdt >= day_start:
            used_today += 1
    if used_today >= api_key.get("daily_request_quota", 0):
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "DAILY_QUOTA_EXCEEDED"
        req_row["error_message"] = "Daily request quota exceeded."
        req_row["result_count"] = 0
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", error_code="DAILY_QUOTA_EXCEEDED")

    if repo is None and not isinstance(configured_repo_id, str):
        req_row["status"] = "failed"
        req_row["error_code"] = "REPO_NOT_CONFIGURED"
        req_row["error_message"] = "Workspace repository not configured."
        req_row["result_count"] = 0
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)
        return _err("CONFLICT", "Workspace repository not configured.", error_code="REPO_NOT_CONFIGURED")

    if repo is None:
        req_row["status"] = "failed"
        req_row["error_code"] = "REPO_NOT_CONFIGURED"
        req_row["error_message"] = "Configured repository not found."
        req_row["result_count"] = 0
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)
        return _err("CONFLICT", "Workspace repository not configured.", error_code="REPO_NOT_CONFIGURED")

    if repo.get("workspace_id") != workspace_id:
        req_row["status"] = "failed"
        req_row["error_code"] = "FORBIDDEN_REPO"
        req_row["error_message"] = "Repository does not belong to workspace."
        req_row["result_count"] = 0
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)
        return _err("UNAUTHORIZED", "Forbidden repository.", error_code="FORBIDDEN_REPO")

    if repo.get("status") != "active":
        req_row["status"] = "failed"
        req_row["error_code"] = "REPO_DISABLED"
        req_row["error_message"] = "Repository is not active."
        req_row["result_count"] = 0
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)
        return _err("CONFLICT", "Repository is disabled.", error_code="REPO_DISABLED")

    # log received before returning (observable dynamics)
    req_logs.append(req_row)
    _save("request_logs.json", req_logs)

    # Search
    q = query.strip().lower()

    # default behavior: exclude stale/deleted unless explicitly asked via status filter
    allowed_statuses = ("active",) if status is None else (status,)
    # Business rule: must not include stale/deleted unless explicitly internal; tool surface isn't internal.
    if status is None:
        allowed_statuses = ("active",)

    def _match_text(hay):
        if not isinstance(hay, str):
            return False
        return q in hay.lower()

    def _dt_ge(val, bound):
        if bound is None:
            return True
        dtv = _parse_dt(val) if isinstance(val, str) else None
        return bool(dtv and dtv >= bound)

    def _dt_le(val, bound):
        if bound is None:
            return True
        dtv = _parse_dt(val) if isinstance(val, str) else None
        return bool(dtv and dtv <= bound)

    results = []
    for r in idx:
        if not isinstance(r, dict):
            continue
        if r.get("repo_id") != repo.get("id"):
            continue
        if r.get("kind") != "file":
            continue
        if r.get("status") not in allowed_statuses:
            continue
        if path_prefix is not None:
            p = r.get("path")
            if not isinstance(p, str) or not p.startswith(path_prefix):
                continue
        if language is not None:
            if (r.get("language") or "").strip() != language:
                continue
        if not _dt_ge(r.get("indexed_at"), ia):
            continue
        if not _dt_le(r.get("indexed_at"), ib):
            continue
        # match query against content_text and path
        if not (_match_text(r.get("content_text")) or _match_text(r.get("path"))):
            continue
        results.append(r)

    # sort
    def _sort_key(r):
        if sort == "indexed_at":
            dtv = _parse_dt(r.get("indexed_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return dtv
        if sort == "path":
            return (r.get("path") or "")
        if sort == "file_size_bytes":
            v = r.get("file_size_bytes")
            return v if isinstance(v, int) else -1
        return 0

    results.sort(key=_sort_key, reverse=(order == "desc"))

    # pagination with cursor as opaque base64 of integer offset; if not decodable, treat as validation error
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                raise ValueError()
        except Exception:
            # update log as failed
            req_logs = _load("request_logs.json")
            for rr in req_logs[::-1]:
                if isinstance(rr, dict) and rr.get("id") == req_row["id"]:
                    rr["status"] = "failed"
                    rr["error_code"] = "VALIDATION_ERROR"
                    rr["error_message"] = "Invalid cursor."
                    rr["result_count"] = 0
                    rr["duration_ms"] = max(0, int((time.time() - t0) * 1000))
                    rr["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
                    break
            _save("request_logs.json", req_logs)
            return _err("VALIDATION_ERROR", "Invalid cursor.")
    page = results[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(results)
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    # update api_key last_used_at on success
    api_key["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    api_key["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("api_keys.json", api_keys)

    # finalize log
    req_logs = _load("request_logs.json")
    for rr in req_logs[::-1]:
        if isinstance(rr, dict) and rr.get("id") == req_row["id"]:
            rr["status"] = "succeeded"
            rr["error_code"] = None
            rr["error_message"] = None
            rr["result_count"] = len(page)
            rr["duration_ms"] = max(0, int((time.time() - t0) * 1000))
            rr["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
            break
    _save("request_logs.json", req_logs)

    return {
        "items": page,
        "total": len(results),
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort": sort,
        "order": order,
    }

def searchIssues(workspace_id, query, issue_state=None, issue_number=None, status=None, indexed_after=None, indexed_before=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0045000" if __import__("os").path.isdir("./environment_mix/0045000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        if isinstance(dt, str):
            return dt
        return now.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _new_id(prefix):
        ts = datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        return f"{prefix}{ts}{os.getpid()}"

    # ---- Validation
    if not isinstance(workspace_id, str) or not re.match(r"^pgs_wsp_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed.")
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query must be a non-empty string.")
    if issue_state is not None and issue_state not in ("open", "closed"):
        return _err("VALIDATION_ERROR", "issue_state must be one of: open, closed.")
    if issue_number is not None and (not isinstance(issue_number, int) or issue_number < 1):
        return _err("VALIDATION_ERROR", "issue_number must be >= 1.")
    if status is not None and status not in ("active", "stale", "deleted"):
        return _err("VALIDATION_ERROR", "status must be one of: active, stale, deleted.")
    ia = _parse_dt(indexed_after) if indexed_after is not None else None
    if indexed_after is not None and ia is None:
        return _err("VALIDATION_ERROR", "indexed_after must be RFC3339 date-time.")
    ib = _parse_dt(indexed_before) if indexed_before is not None else None
    if indexed_before is not None and ib is None:
        return _err("VALIDATION_ERROR", "indexed_before must be RFC3339 date-time.")
    if ia and ib and ia > ib:
        return _err("VALIDATION_ERROR", "indexed_after must be <= indexed_before.")
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sort is None:
        sort = "indexed_at"
    if sort not in ("indexed_at", "issue_number"):
        return _err("VALIDATION_ERROR", "sort must be one of: indexed_at, issue_number.")
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc.")

    parameters_json = {"workspace_id": workspace_id, "query": query}
    if issue_state is not None: parameters_json["issue_state"] = issue_state
    if issue_number is not None: parameters_json["issue_number"] = issue_number
    if status is not None: parameters_json["status"] = status
    if indexed_after is not None: parameters_json["indexed_after"] = indexed_after
    if indexed_before is not None: parameters_json["indexed_before"] = indexed_before
    if limit is not None: parameters_json["limit"] = limit
    if cursor is not None: parameters_json["cursor"] = cursor
    if sort is not None: parameters_json["sort"] = sort
    if order is not None: parameters_json["order"] = order

    workspaces = _load("workspaces.json")
    repos = _load("repositories.json")
    api_keys = _load("api_keys.json")
    idx = _load("repo_content_index.json")
    req_logs = _load("request_logs.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Workspace is not active.")

    configured_repo_id = ws.get("configured_repo_id")
    repo = None
    if isinstance(configured_repo_id, str):
        repo = next((r for r in repos if isinstance(r, dict) and r.get("id") == configured_repo_id and r.get("workspace_id") == workspace_id), None)
    if repo is None:
        repo = next((r for r in repos if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("status") == "active"), None)

    api_key = next((k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    api_key_id = api_key.get("id") if api_key else None
    repo_id_for_log = repo.get("id") if repo else (configured_repo_id if isinstance(configured_repo_id, str) else "pgs_rep_000000000000000000")

    req_row = {
        "id": _new_id("pgs_rql_"),
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "repo_id": repo_id_for_log,
        "tool_name": "searchIssues",
        "parameters_json": parameters_json,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "result_count": None,
        "duration_ms": None,
        "client_ip": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    if api_key is None:
        req_row["status"] = "failed"
        req_row["error_code"] = "UNAUTHORIZED"
        req_row["error_message"] = "No active API key for workspace."
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)
        return _err("UNAUTHORIZED", "No active API key for workspace.")

    def _dt_from_iso(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    rl_window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in req_logs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != api_key_id:
            continue
        cdt = _dt_from_iso(r.get("created_at"))
        if cdt and cdt >= rl_window_start:
            recent += 1
    if recent >= api_key.get("rate_limit_per_minute", 0):
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "RATE_LIMIT"
        req_row["error_message"] = "Rate limit exceeded."
        req_row["result_count"] = 0
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)
        return _err("RATE_LIMIT", "Rate limit exceeded.", error_code="RATE_LIMIT")

    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
    used_today = 0
    for r in req_logs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != api_key_id:
            continue
        if r.get("status") not in ("succeeded", "failed"):
            continue
        cdt = _dt_from_iso(r.get("created_at"))
        if cdt and cdt >= day_start:
            used_today += 1
    if used_today >= api_key.get("daily_request_quota", 0):
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "DAILY_QUOTA_EXCEEDED"
        req_row["error_message"] = "Daily request quota exceeded."
        req_row["result_count"] = 0
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", error_code="DAILY_QUOTA_EXCEEDED")

    if repo is None and not isinstance(configured_repo_id, str):
        req_row["status"] = "failed"
        req_row["error_code"] = "REPO_NOT_CONFIGURED"
        req_row["error_message"] = "Workspace repository not configured."
        req_row["result_count"] = 0
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)
        return _err("CONFLICT", "Workspace repository not configured.", error_code="REPO_NOT_CONFIGURED")

    if repo is None:
        req_row["status"] = "failed"
        req_row["error_code"] = "REPO_NOT_CONFIGURED"
        req_row["error_message"] = "Configured repository not found."
        req_row["result_count"] = 0
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)
        return _err("CONFLICT", "Workspace repository not configured.", error_code="REPO_NOT_CONFIGURED")

    if repo.get("workspace_id") != workspace_id:
        req_row["status"] = "failed"
        req_row["error_code"] = "FORBIDDEN_REPO"
        req_row["error_message"] = "Repository does not belong to workspace."
        req_row["result_count"] = 0
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)
        return _err("UNAUTHORIZED", "Forbidden repository.", error_code="FORBIDDEN_REPO")

    if repo.get("status") != "active":
        req_row["status"] = "failed"
        req_row["error_code"] = "REPO_DISABLED"
        req_row["error_message"] = "Repository is not active."
        req_row["result_count"] = 0
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)
        return _err("CONFLICT", "Repository is disabled.", error_code="REPO_DISABLED")

    req_logs.append(req_row)
    _save("request_logs.json", req_logs)

    q = query.strip().lower()
    allowed_statuses = ("active",) if status is None else (status,)
    # business rule: must not include deleted issues; and must not include stale unless explicitly asked
    if status is None:
        allowed_statuses = ("active",)
    if "deleted" in allowed_statuses:
        allowed_statuses = tuple(s for s in allowed_statuses if s != "deleted")

    def _match(hay):
        if not isinstance(hay, str):
            return False
        return q in hay.lower()

    def _dt_ge(val, bound):
        if bound is None:
            return True
        dtv = _parse_dt(val) if isinstance(val, str) else None
        return bool(dtv and dtv >= bound)

    def _dt_le(val, bound):
        if bound is None:
            return True
        dtv = _parse_dt(val) if isinstance(val, str) else None
        return bool(dtv and dtv <= bound)

    results = []
    for r in idx:
        if not isinstance(r, dict):
            continue
        if r.get("repo_id") != repo.get("id"):
            continue
        if r.get("kind") != "issue":
            continue
        if r.get("status") not in allowed_statuses:
            continue
        if issue_state is not None and r.get("issue_state") != issue_state:
            continue
        if issue_number is not None and r.get("issue_number") != issue_number:
            continue
        if not _dt_ge(r.get("indexed_at"), ia):
            continue
        if not _dt_le(r.get("indexed_at"), ib):
            continue
        if not (_match(r.get("issue_title")) or _match(r.get("issue_body_text"))):
            continue
        results.append(r)

    def _sort_key(r):
        if sort == "indexed_at":
            return _parse_dt(r.get("indexed_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if sort == "issue_number":
            v = r.get("issue_number")
            return v if isinstance(v, int) else 0
        return 0

    results.sort(key=_sort_key, reverse=(order == "desc"))

    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                raise ValueError()
        except Exception:
            req_logs = _load("request_logs.json")
            for rr in req_logs[::-1]:
                if isinstance(rr, dict) and rr.get("id") == req_row["id"]:
                    rr["status"] = "failed"
                    rr["error_code"] = "VALIDATION_ERROR"
                    rr["error_message"] = "Invalid cursor."
                    rr["result_count"] = 0
                    rr["duration_ms"] = max(0, int((time.time() - t0) * 1000))
                    rr["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
                    break
            _save("request_logs.json", req_logs)
            return _err("VALIDATION_ERROR", "Invalid cursor.")
    page = results[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(results)
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    api_key["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    api_key["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("api_keys.json", api_keys)

    req_logs = _load("request_logs.json")
    for rr in req_logs[::-1]:
        if isinstance(rr, dict) and rr.get("id") == req_row["id"]:
            rr["status"] = "succeeded"
            rr["error_code"] = None
            rr["error_message"] = None
            rr["result_count"] = len(page)
            rr["duration_ms"] = max(0, int((time.time() - t0) * 1000))
            rr["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
            break
    _save("request_logs.json", req_logs)

    return {
        "items": page,
        "total": len(results),
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort": sort,
        "order": order,
    }

def getCommitHistory(workspace_id, days, path_prefix=None, author=None, since=None, until=None, status=None, limit=None, cursor=None, include_diffs=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64
