        return _err("VALIDATION_ERROR", "author must be a non-empty string when provided.")
    s_dt = _parse_dt(since) if since is not None else None
    if since is not None and s_dt is None:
        return _err("VALIDATION_ERROR", "since must be RFC3339 date-time.")
