    if status is not None: parameters_json["status"] = status
    if limit is not None: parameters_json["limit"] = limit
    if cursor is not None: parameters_json["cursor"] = cursor
    if include_diffs is not None: parameters_json["include_diffs"] = include_diffs
    if sort is not None: parameters_json["sort"] = sort
    if order is not None: parameters_json["order"] = order

    workspaces = _load("workspaces.json")
    repos = _load("repositories.json")
    api_keys = _load("api_keys.json")
    idx = _load("repo_content_index.json")
    req_logs = _load("request_logs.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Workspace is not active.")

    configured_repo_id = ws.get("configured_repo_id")
    repo = None
    if isinstance(configured_repo_id, str):
        repo = next((r for r in repos if isinstance(r, dict) and r.get("id") == configured_repo_id and r.get("workspace_id") == workspace_id), None)
    if repo is None:
        repo = next((r for r in repos if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("status") == "active"), None)

    api_key = next((k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    api_key_id = api_key.get("id") if api_key else None
    repo_id_for_log = repo.get("id") if repo else (configured_repo_id if isinstance(configured_repo_id, str) else "pgs_rep_000000000000000000")

    req_row = {
        "id": _new_id("pgs_rql_"),
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "repo_id": repo_id_for_log,
        "tool_name": "getCommitHistory",
        "parameters_json": parameters_json,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "result_count": None,
        "duration_ms": None,
        "client_ip": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    if api_key is None:
        req_row["status"] = "failed"
        req_row["error_code"] = "UNAUTHORIZED"
        req_row["error_message"] = "No active API key for workspace."
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)
        return _err("UNAUTHORIZED", "No active API key for workspace.")

    def _dt_from_iso(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    rl_window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in req_logs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != api_key_id:
            continue
        cdt = _dt_from_iso(r.get("created_at"))
        if cdt and cdt >= rl_window_start:
            recent += 1
    if recent >= api_key.get("rate_limit_per_minute", 0):
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "RATE_LIMIT"
        req_row["error_message"] = "Rate limit exceeded."
        req_row["result_count"] = 0
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)
        return _err("RATE_LIMIT", "Rate limit exceeded.", error_code="RATE_LIMIT")

    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
    used_today = 0
    for r in req_logs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != api_key_id:
            continue
        if r.get("status") not in ("succeeded", "failed"):
            continue
        cdt = _dt_from_iso(r.get("created_at"))
        if cdt and cdt >= day_start:
            used_today += 1
    if used_today >= api_key.get("daily_request_quota", 0):
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "DAILY_QUOTA_EXCEEDED"
        req_row["error_message"] = "Daily request quota exceeded."
        req_row["result_count"] = 0
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", error_code="DAILY_QUOTA_EXCEEDED")

    if repo is None and not isinstance(configured_repo_id, str):
        req_row["status"] = "failed"
        req_row["error_code"] = "REPO_NOT_CONFIGURED"
        req_row["error_message"] = "Workspace repository not configured."
        req_row["result_count"] = 0
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)
        return _err("CONFLICT", "Workspace repository not configured.", error_code="REPO_NOT_CONFIGURED")

    if repo is None:
        req_row["status"] = "failed"
        req_row["error_code"] = "REPO_NOT_CONFIGURED"
        req_row["error_message"] = "Configured repository not found."
        req_row["result_count"] = 0
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)
        return _err("CONFLICT", "Workspace repository not configured.", error_code="REPO_NOT_CONFIGURED")

    if repo.get("workspace_id") != workspace_id:
        req_row["status"] = "failed"
        req_row["error_code"] = "FORBIDDEN_REPO"
        req_row["error_message"] = "Repository does not belong to workspace."
        req_row["result_count"] = 0
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)
        return _err("UNAUTHORIZED", "Forbidden repository.", error_code="FORBIDDEN_REPO")

    if repo.get("status") != "active":
        req_row["status"] = "failed"
        req_row["error_code"] = "REPO_DISABLED"
        req_row["error_message"] = "Repository is not active."
        req_row["result_count"] = 0
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_logs.append(req_row)
        _save("request_logs.json", req_logs)
        return _err("CONFLICT", "Repository is disabled.", error_code="REPO_DISABLED")

    req_logs.append(req_row)
    _save("request_logs.json", req_logs)

    # time window
    if s_dt is None:
        s_dt = now - datetime.timedelta(days=days)
    if u_dt is None:
        u_dt = now

    # default: exclude stale/deleted unless explicitly asked (tool surface isn't internal)
    allowed_statuses = ("active",) if status is None else (status,)

    def _commit_dt(r):
        return _parse_dt(r.get("commit_timestamp")) if isinstance(r, dict) else None

    results = []
    for r in idx:
        if not isinstance(r, dict):
            continue
        if r.get("repo_id") != repo.get("id"):
            continue
        if r.get("kind") != "commit":
            continue
        if r.get("status") not in allowed_statuses:
            continue
        cdt = _commit_dt(r)
        if not cdt:
            continue
        if cdt < s_dt or cdt > u_dt:
            continue
        if author is not None:
            if not isinstance(r.get("commit_author"), str) or author.lower() not in r.get("commit_author").lower():
                continue
        if path_prefix is not None:
            files = r.get("commit_files_changed")
            ok = False
            if isinstance(files, list):
                for f in files:
                    if isinstance(f, dict) and isinstance(f.get("path"), str) and f.get("path").startswith(path_prefix):
                        ok = True
                        break
            if not ok:
                continue
        results.append(r)

    # sort by commit_timestamp only
    results.sort(key=lambda r: _commit_dt(r) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), reverse=(order == "desc"))

    # cursor: base64 offset
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                raise ValueError()
        except Exception:
            req_logs = _load("request_logs.json")
            for rr in req_logs[::-1]:
                if isinstance(rr, dict) and rr.get("id") == req_row["id"]:
                    rr["status"] = "failed"
                    rr["error_code"] = "VALIDATION_ERROR"
                    rr["error_message"] = "Invalid cursor."
                    rr["result_count"] = 0
                    rr["duration_ms"] = max(0, int((time.time() - t0) * 1000))
                    rr["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
                    break
            _save("request_logs.json", req_logs)
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    page = results[offset:offset + limit]
    has_more = (offset + len(page)) < len(results)
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(offset + len(page)).encode("utf-8")).decode("utf-8").rstrip("=")

    # include_diffs controls whether to include commit_files_changed
    items = []
    for r in page:
        if include_diffs:
            items.append(r)
        else:
            rr = dict(r)
            rr.pop("commit_files_changed", None)
            items.append(rr)

    api_key["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    api_key["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("api_keys.json", api_keys)

    req_logs = _load("request_logs.json")
    for rr in req_logs[::-1]:
        if isinstance(rr, dict) and rr.get("id") == req_row["id"]:
            rr["status"] = "succeeded"
            rr["error_code"] = None
            rr["error_message"] = None
            rr["result_count"] = len(items)
            rr["duration_ms"] = max(0, int((time.time() - t0) * 1000))
            rr["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
            break
    _save("request_logs.json", req_logs)

    return {
        "items": items,
        "total": len(results),
        "has_more": has_more,
        "next_cursor": next_cursor,
        "since": _iso(s_dt),
        "until": _iso(u_dt),
        "sort": "commit_timestamp",
        "order": order,
    }

def getWorkspace(workspace_id, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0045000" if __import__("os").path.isdir("./environment_mix/0045000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return _now().isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v:
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        # Deterministic-ish, uppercase, >= 18 chars after prefix requirement
        raw = uuid.uuid4().hex.upper() + uuid.uuid4().hex.upper()
        return f"{prefix}{raw[:22]}"

    t0 = time.time()
    workspaces = _load("workspaces.json")
    repos = _load("repositories.json")
    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")

    # ---- validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^pgs_wsp_[0-9A-Z]{18,}$", workspace_id or ""):
        return _err("VALIDATION_ERROR", "Malformed workspace_id.")

    # ---- ambient auth: resolve a usable active api key + active workspace
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None or ws.get("status") == "deleted":
        return _err("NOT_FOUND", "Workspace not found.")

    # Find an active api key for this workspace (per business rule: tools require active api key + active workspace)
    key = next((k for k in api_keys if k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if ws.get("status") != "active" or key is None:
        return _err("UNAUTHORIZED", "Not authorized for this workspace.")

    # request logging required for exposed tools getFileContents/searchFiles/searchIssues/getCommitHistory only.
    # This tool is an admin/config surface; schema enum does not include it, so we do not write request_logs here.

    # Return workspace fields
    out = {
        "id": ws.get("id"),
        "name": ws.get("name"),
        "configured_repo_id": ws.get("configured_repo_id"),
        "status": ws.get("status"),
        "created_at": ws.get("created_at"),
        "updated_at": ws.get("updated_at"),
    }
    return {"workspace": out}

def updateWorkspace(workspace_id, name=None, configured_repo_id=None, status=None, **_extra):
    import json, os, datetime, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0045000" if __import__("os").path.isdir("./environment_mix/0045000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        if isinstance(dt, str):
            return dt
        return now.isoformat().replace("+00:00", "Z")

    # ---- validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^pgs_wsp_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed.")

    if name is not None:
        if not isinstance(name, str):
            return _err("VALIDATION_ERROR", "name must be a string.")
        if len(name) < 1 or len(name) > 200:
            return _err("VALIDATION_ERROR", "name must be between 1 and 200 characters.")

    # configured_repo_id is nullable; accept any string here and validate existence/ownership in business rules.
    if configured_repo_id is not None and not isinstance(configured_repo_id, str):
        return _err("VALIDATION_ERROR", "configured_repo_id must be a string or null.")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "suspended", "deleted"):
            return _err("VALIDATION_ERROR", "status must be one of: active, suspended, deleted.")

    workspaces = _load("workspaces.json")
    repos = _load("repositories.json")

    ws_idx = None
    for i, w in enumerate(workspaces):
        if isinstance(w, dict) and w.get("id") == workspace_id:
            ws_idx = i
            break
    if ws_idx is None:
        return _err("NOT_FOUND", "Workspace not found.")
    ws = workspaces[ws_idx]

    # cannot modify deleted workspace
    if ws.get("status") == "deleted":
        return _err("INVALID_TRANSITION", "Cannot modify a deleted workspace.")

    # unique(name)
    if name is not None:
        for w in workspaces:
            if not isinstance(w, dict):
                continue
            if w.get("id") != workspace_id and w.get("name") == name:
                return _err("CONFLICT", "Workspace name must be unique.", rule="unique(name)")

    # validate configured_repo_id reference and ownership when set (business rule / FK)
    if configured_repo_id is not None:
        repo = next((r for r in repos if isinstance(r, dict) and r.get("id") == configured_repo_id), None)
        if repo is None:
            return _err("NOT_FOUND", "configured_repo_id does not reference an existing repository.", rule="configured_repo_id references repositories.id")
        if repo.get("workspace_id") != workspace_id:
            return _err("CONFLICT", "configured_repo_id must reference a repository in the same workspace.", rule="FK repositories.workspace_id must equal workspaces.id")

    # lifecycle transition
    if status is not None and status != ws.get("status"):
        transitions = {
            "active": ("suspended", "deleted"),
            "suspended": ("active", "deleted"),
            "deleted": (),
        }
        cur = ws.get("status")
        allowed = transitions.get(cur, ())
        if status not in allowed:
            return _err("INVALID_TRANSITION", f"Invalid status transition: {cur} -> {status}.")
        ws["status"] = status

    mutated = False
    if name is not None and name != ws.get("name"):
        ws["name"] = name
        mutated = True
    if configured_repo_id is not None:
        # allow setting to any repository id (even if not active); tools will enforce active/disabled later.
        if ws.get("configured_repo_id") != configured_repo_id:
            ws["configured_repo_id"] = configured_repo_id
            mutated = True
    # allow clearing configuration explicitly by passing null (represented by configured_repo_id=None)
    # In Python signature default is None, so caller can't distinguish "not provided" vs "null" unless they pass it.
    # Here, if they pass configured_repo_id=None explicitly it is same; treat as clearing only when _extra indicates explicit null? Not available.
    # Therefore we clear only when configured_repo_id is exactly None AND the caller intended it cannot be known; keep current behavior (no change).

    # If no actual changes and no status transition occurred, return NOT_FOUND-equivalent? Real APIs often idempotently return the row.
    # But contract requires no success without effect for mutations. If caller provided no mutable fields, this is a validation error.
    if name is None and configured_repo_id is None and status is None:
        return _err("VALIDATION_ERROR", "No fields to update.")

    # If only status transition or only name/repo changed, ensure effect occurred.
    if not mutated and (status is None or status == ws.get("status")):
        # nothing changed
        return _err("CONFLICT", "No changes applied.")

    ws["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    workspaces[ws_idx] = ws
    _save("workspaces.json", workspaces)

    return ws

def listRepositories(workspace_id, status=None, github_owner=None, github_repo=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0045000" if __import__("os").path.isdir("./environment_mix/0045000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v:
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _cursor_encode(obj):
        b = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _cursor_decode(cur):
        if not isinstance(cur, str) or not cur:
            return None
        s = cur.strip()
        pad = "=" * (-len(s) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    workspaces = _load("workspaces.json")
    repos = _load("repositories.json")
    api_keys = _load("api_keys.json")

    # ---- validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^pgs_wsp_[0-9A-Z]{18,}$", workspace_id or ""):
        return _err("VALIDATION_ERROR", "Malformed workspace_id.")

    if status is not None and (not isinstance(status, str) or status not in ("active", "disabled", "deleted")):
        return _err("VALIDATION_ERROR", "Invalid status filter.")

    if github_owner is not None and not isinstance(github_owner, str):
        return _err("VALIDATION_ERROR", "github_owner must be a string.")

    if github_repo is not None and not isinstance(github_repo, str):
        return _err("VALIDATION_ERROR", "github_repo must be a string.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")

    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "last_indexed_at", "github_owner", "github_repo"):
        return _err("VALIDATION_ERROR", "Invalid sort field.")

    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Invalid order.")

    cur = None
    if cursor is not None:
        cur = _cursor_decode(cursor)
        if cur is None or not isinstance(cur, dict) or "v" not in cur:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # ---- auth
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None or ws.get("status") == "deleted":
        return _err("NOT_FOUND", "Workspace not found.")
    key = next((k for k in api_keys if k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if key is None:
        return _err("UNAUTHORIZED", "Not authorized for this workspace.")

    # ---- filter
    rows = [r for r in repos if r.get("workspace_id") == workspace_id]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if github_owner is not None:
        go = github_owner.lower()
        rows = [r for r in rows if isinstance(r.get("github_owner"), str) and r.get("github_owner").lower() == go]
    if github_repo is not None:
        gr = github_repo.lower()
        rows = [r for r in rows if isinstance(r.get("github_repo"), str) and r.get("github_repo").lower() == gr]

    # ---- sort
    reverse = (order == "desc")

    def _sort_key(r):
        if sort in ("created_at", "updated_at", "last_indexed_at"):
            dt = _parse_dt(r.get(sort)) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (dt, r.get("id") or "")
        return ((r.get(sort) or "").lower(), r.get("id") or "")

    rows.sort(key=_sort_key, reverse=reverse)

    # ---- pagination using cursor with last sort key
    start = 0
    if cur is not None:
        if cur.get("sort") != sort or cur.get("order") != order:
            return _err("VALIDATION_ERROR", "Cursor does not match sort/order.")
        last_id = cur.get("last_id")
        last_val = cur.get("last_val")
        # find position after the last seen
        def _val_for(r):
            if sort in ("created_at", "updated_at", "last_indexed_at"):
                dt = _parse_dt(r.get(sort)) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
                return dt.isoformat()
            return (r.get(sort) or "").lower()

        for i, r in enumerate(rows):
            if r.get("id") == last_id and _val_for(r) == last_val:
                start = i + 1
                break

    page = rows[start:start + limit]
    has_more = (start + limit) < len(rows)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        if sort in ("created_at", "updated_at", "last_indexed_at"):
            dt = _parse_dt(last.get(sort)) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            last_val = dt.isoformat()
        else:
            last_val = (last.get(sort) or "").lower()
        next_cursor = _cursor_encode({"v": 1, "sort": sort, "order": order, "last_id": last.get("id"), "last_val": last_val})

    # ---- envelope
    return {
        "repositories": page,
        "pagination": {
            "total": len(rows),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def createRepository(workspace_id, github_owner, github_repo, default_branch, installation_type, credential_secret_ref, status=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0045000" if __import__("os").path.isdir("./environment_mix/0045000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return _now().isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        raw = uuid.uuid4().hex.upper() + uuid.uuid4().hex.upper()
        return f"{prefix}{raw[:22]}"

    workspaces = _load("workspaces.json")
    repos = _load("repositories.json")
    api_keys = _load("api_keys.json")

    # ---- validate
    if not isinstance(workspace_id, str) or not re.match(r"^pgs_wsp_[0-9A-Z]{18,}$", workspace_id or ""):
        return _err("VALIDATION_ERROR", "Malformed workspace_id.")

    if not isinstance(github_owner, str) or not (1 <= len(github_owner) <= 200):
        return _err("VALIDATION_ERROR", "github_owner must be a string between 1 and 200 characters.")
    if not isinstance(github_repo, str) or not (1 <= len(github_repo) <= 200):
        return _err("VALIDATION_ERROR", "github_repo must be a string between 1 and 200 characters.")
    if not isinstance(default_branch, str) or not (1 <= len(default_branch) <= 255):
        return _err("VALIDATION_ERROR", "default_branch must be a string between 1 and 255 characters.")
    if default_branch.strip() == "":
        return _err("VALIDATION_ERROR", "default_branch must not be empty.")

    if not isinstance(installation_type, str) or installation_type not in ("github_app", "personal_access_token"):
        return _err("VALIDATION_ERROR", "installation_type must be one of: github_app, personal_access_token.")

    if not isinstance(credential_secret_ref, str) or not (1 <= len(credential_secret_ref) <= 500):
        return _err("VALIDATION_ERROR", "credential_secret_ref must be a string between 1 and 500 characters.")

    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in ("active", "disabled", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid status.")

    # ---- auth
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None or ws.get("status") == "deleted":
        return _err("NOT_FOUND", "Workspace not found.")
    key = next((k for k in api_keys if k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if key is None or ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Not authorized for this workspace.")

    # ---- conflict: unique(workspace_id, github_owner, github_repo) for non-deleted
    for r in repos:
        if r.get("workspace_id") == workspace_id and (r.get("github_owner") == github_owner) and (r.get("github_repo") == github_repo):
            if r.get("status") != "deleted":
                return _err("CONFLICT", "Repository already exists in this workspace.")

    # ---- map installation_type to schema enum (pat/github_app)
    inst = "github_app" if installation_type == "github_app" else "pat"

    now = _iso(_now())
    new_row = {
        "id": _new_id("pgs_rep_"),
        "workspace_id": workspace_id,
        "github_owner": github_owner,
        "github_repo": github_repo,
        "default_branch": default_branch,
        "installation_type": inst,
        "credential_secret_ref": credential_secret_ref,
        "status": status,
        "last_indexed_at": None,
        "created_at": now,
        "updated_at": now,
    }

    repos.append(new_row)
    _save("repositories.json", repos)

    return {"repository": new_row}

def updateRepository(workspace_id, repo_id, default_branch=None, credential_secret_ref=None, status=None, **_extra):
    import json, os, datetime, time, re, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0045000" if __import__("os").path.isdir("./environment_mix/0045000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return _now().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        # vendor-like: pgs_rep_ + >=18 base36-ish uppercase
        alphabet = string.ascii_uppercase + string.digits
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(22))

    def _log_request(request_logs, workspace_id_val, api_key_id_val, repo_id_val, tool_name, params_obj, status_val, error_code=None, error_message=None, result_count=None, start_dt=None, duration_ms=None):
        nowdt = _now()
        if start_dt is None:
            start_dt = nowdt
        if duration_ms is None:
            duration_ms = int(max(0, (nowdt - start_dt).total_seconds() * 1000))
        row = {
            "id": _new_id("pgs_rql"),
            "workspace_id": workspace_id_val,
            "api_key_id": api_key_id_val,
            "repo_id": repo_id_val,
            "tool_name": tool_name,
            "parameters_json": params_obj if isinstance(params_obj, dict) else {},
            "status": status_val,
            "error_code": error_code,
            "error_message": error_message,
            "result_count": result_count,
            "duration_ms": duration_ms,
            "client_ip": None,
            "created_at": _iso(start_dt),
            "updated_at": _iso(nowdt),
        }
        request_logs.append(row)
        return row

    start = _now()

    # ---- Validate inputs (types/patterns/ranges) ----
    if not isinstance(workspace_id, str) or not re.match(r"^pgs_wsp_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(repo_id, str) or not re.match(r"^pgs_rep_[0-9A-Z]{18,}$", repo_id):
        return _err("VALIDATION_ERROR", "Invalid repo_id.")
    if default_branch is not None:
        if not isinstance(default_branch, str):
            return _err("VALIDATION_ERROR", "default_branch must be a string.")
        if len(default_branch) < 1 or len(default_branch) > 255:
            return _err("VALIDATION_ERROR", "default_branch length must be between 1 and 255.")
    if credential_secret_ref is not None:
        if not isinstance(credential_secret_ref, str):
            return _err("VALIDATION_ERROR", "credential_secret_ref must be a string.")
        if len(credential_secret_ref) < 1 or len(credential_secret_ref) > 500:
            return _err("VALIDATION_ERROR", "credential_secret_ref length must be between 1 and 500.")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled", "deleted"):
            return _err("VALIDATION_ERROR", "status must be one of: active, disabled, deleted.")

    # ---- Load datastore ----
    workspaces = _load("workspaces.json")
    repos = _load("repositories.json")
    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")

    # ---- Ambient auth resolution (must find a working combination) ----
    wsp = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not wsp:
        # No place to log under correct workspace; still return NOT_FOUND.
        return _err("NOT_FOUND", "Workspace not found.")
    if wsp.get("status") != "active":
        return _err("UNAUTHORIZED", "Workspace is not active.")

    repo = next((r for r in repos if r.get("id") == repo_id), None)
    if not repo:
        # We can log with repo_id even if missing? FK would be violated; avoid logging and return NOT_FOUND.
        return _err("NOT_FOUND", "Repository not found.")

    # FK integrity: repo.workspace_id must equal provided workspace_id
    if repo.get("workspace_id") != workspace_id:
        # Must be rejected and logged failed with FORBIDDEN_REPO
        # Need an api key context: pick any active key in this workspace (ambient).
        api_key = next((k for k in api_keys if k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
        # Log only if repo belongs to workspace via repositories.workspace_id (it doesn't); but rule says log with failed/forbidden.
        # We'll log using the requested repo_id anyway (even though FK would not validate in a strict DB);
        # datastore is JSON, so we can still record the attempt.
        _log_request(request_logs, workspace_id, api_key.get("id") if api_key else None, repo_id, "updateRepository", {
            "workspace_id": workspace_id, "repo_id": repo_id, **({} if default_branch is None else {"default_branch": default_branch}),
            **({} if credential_secret_ref is None else {"credential_secret_ref": credential_secret_ref}),
            **({} if status is None else {"status": status}),
        }, "failed", error_code="FORBIDDEN_REPO", error_message="Repository does not belong to workspace.", start_dt=start)
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "FORBIDDEN_REPO", error_code="FORBIDDEN_REPO")

    # Resolve an active API key for this workspace to execute (ambient)
    api_key = next((k for k in api_keys if k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if not api_key:
        # No combination can serve the call
        return _err("UNAUTHORIZED", "No active API key available for this workspace.")

    # ---- Enforce rate limits / quota before performing mutation; must log every invocation ----
    # compute counts based on existing request_logs
    nowdt = _now()
    window_start = nowdt - datetime.timedelta(seconds=60)
    day_start = nowdt.replace(hour=0, minute=0, second=0, microsecond=0)

    api_key_id = api_key.get("id")
    rate_limit = api_key.get("rate_limit_per_minute")
    daily_quota = api_key.get("daily_request_quota")

    if not isinstance(rate_limit, int) or rate_limit < 1 or rate_limit > 6000:
        # datastore invalid; treat as server error object without raising
        # still log failed
        _log_request(request_logs, workspace_id, api_key_id, repo_id, "updateRepository", {
            "workspace_id": workspace_id, "repo_id": repo_id, **({} if default_branch is None else {"default_branch": default_branch}),
            **({} if credential_secret_ref is None else {"credential_secret_ref": credential_secret_ref}),
            **({} if status is None else {"status": status}),
        }, "failed", error_code="VALIDATION_ERROR", error_message="API key rate limit misconfigured.", start_dt=start)
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "API key rate limit misconfigured.")
    if not isinstance(daily_quota, int) or daily_quota < 1 or daily_quota > 1000000:
        _log_request(request_logs, workspace_id, api_key_id, repo_id, "updateRepository", {
            "workspace_id": workspace_id, "repo_id": repo_id, **({} if default_branch is None else {"default_branch": default_branch}),
            **({} if credential_secret_ref is None else {"credential_secret_ref": credential_secret_ref}),
            **({} if status is None else {"status": status}),
        }, "failed", error_code="VALIDATION_ERROR", error_message="API key daily quota misconfigured.", start_dt=start)
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "API key daily quota misconfigured.")

    recent = 0
    daily = 0
    for rl in request_logs:
        if rl.get("api_key_id") != api_key_id:
            continue
        created = _parse_dt(rl.get("created_at"))
        if created and created >= window_start:
            recent += 1
        if created and created >= day_start and rl.get("status") in ("succeeded", "failed"):
            daily += 1

    params_obj = {
        "workspace_id": workspace_id,
        "repo_id": repo_id
    }
    if default_branch is not None:
        params_obj["default_branch"] = default_branch
    if credential_secret_ref is not None:
        params_obj["credential_secret_ref"] = credential_secret_ref
    if status is not None:
        params_obj["status"] = status

    # Daily quota check (reaches quota => reject)
    if daily >= daily_quota:
        _log_request(request_logs, workspace_id, api_key_id, repo_id, "updateRepository", params_obj,
                     "rate_limited", error_code="DAILY_QUOTA_EXCEEDED", error_message="Daily request quota exceeded.", start_dt=start)
        _save("request_logs.json", request_logs)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", error_code="DAILY_QUOTA_EXCEEDED")

    # Rate limit check (exceeds rate => reject)
    if recent >= rate_limit:
        _log_request(request_logs, workspace_id, api_key_id, repo_id, "updateRepository", params_obj,
                     "rate_limited", error_code="RATE_LIMIT_EXCEEDED", error_message="Rate limit exceeded.", start_dt=start)
        _save("request_logs.json", request_logs)
        return _err("RATE_LIMIT", "Rate limit exceeded.", error_code="RATE_LIMIT_EXCEEDED")

    # Create initial received log row
    log_row = _log_request(request_logs, workspace_id, api_key_id, repo_id, "updateRepository", params_obj,
                           "received", start_dt=start)
    _save("request_logs.json", request_logs)

    # ---- Business rules & mutation ----
    # Reject updates to deleted repositories
    if repo.get("status") == "deleted":
        # transition received->failed
        log_row["status"] = "failed"
        log_row["error_code"] = "INVALID_TRANSITION"
        log_row["error_message"] = "Cannot update a deleted repository."
        log_row["updated_at"] = _iso(_now())
        log_row["duration_ms"] = int(max(0, (_now() - start).total_seconds() * 1000))
        _save("request_logs.json", request_logs)
        return _err("INVALID_TRANSITION", "Cannot update a deleted repository.")

    # Prevent unsafe changes to immutable identity fields: github_owner, github_repo, installation_type, workspace_id are immutable here.
    # Tool surface doesn't include them, so only enforce that no-op update must still have effect.
    allowed_updates = {}
    if default_branch is not None and default_branch != repo.get("default_branch"):
        if default_branch.strip() == "":
            log_row["status"] = "failed"
            log_row["error_code"] = "VALIDATION_ERROR"
            log_row["error_message"] = "default_branch must not be empty."
            log_row["updated_at"] = _iso(_now())
            log_row["duration_ms"] = int(max(0, (_now() - start).total_seconds() * 1000))
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "default_branch must not be empty.")
        allowed_updates["default_branch"] = default_branch

    if credential_secret_ref is not None and credential_secret_ref != repo.get("credential_secret_ref"):
        if credential_secret_ref.strip() == "":
            log_row["status"] = "failed"
            log_row["error_code"] = "VALIDATION_ERROR"
            log_row["error_message"] = "credential_secret_ref must not be empty."
            log_row["updated_at"] = _iso(_now())
            log_row["duration_ms"] = int(max(0, (_now() - start).total_seconds() * 1000))
            _save("request_logs.json", request_logs)
            return _err("VALIDATION_ERROR", "credential_secret_ref must not be empty.")
        allowed_updates["credential_secret_ref"] = credential_secret_ref

    # Status transition validation
    if status is not None and status != repo.get("status"):
        transitions = {"active": ["disabled", "deleted"], "disabled": ["active", "deleted"], "deleted": []}
        cur = repo.get("status")
        if cur not in transitions or status not in transitions.get(cur, []):
            log_row["status"] = "failed"
            log_row["error_code"] = "INVALID_TRANSITION"
            log_row["error_message"] = f"Invalid status transition {cur} -> {status}."
            log_row["updated_at"] = _iso(_now())
            log_row["duration_ms"] = int(max(0, (_now() - start).total_seconds() * 1000))
            _save("request_logs.json", request_logs)
            return _err("INVALID_TRANSITION", f"Invalid status transition {cur} -> {status}.")
        allowed_updates["status"] = status

    if not allowed_updates:
        # No success without effect
        log_row["status"] = "failed"
        log_row["error_code"] = "CONFLICT"
        log_row["error_message"] = "No changes detected."
        log_row["updated_at"] = _iso(_now())
        log_row["duration_ms"] = int(max(0, (_now() - start).total_seconds() * 1000))
        _save("request_logs.json", request_logs)
        return _err("CONFLICT", "No changes detected.")

    # Apply updates
    now_iso = _iso(_now())
    for k, v in allowed_updates.items():
        repo[k] = v
    repo["updated_at"] = now_iso

    # Persist repos
    _save("repositories.json", repos)

    # Update api key last_used_at on successful use
    api_key["last_used_at"] = now_iso
    api_key["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    # Finalize request log
    log_row["status"] = "succeeded"
    log_row["result_count"] = 1
    log_row["updated_at"] = _iso(_now())
    log_row["duration_ms"] = int(max(0, (_now() - start).total_seconds() * 1000))
    _save("request_logs.json", request_logs)

    return {
        "repository": repo,
        "request": {
            "id": log_row.get("id"),
            "status": log_row.get("status"),
            "duration_ms": log_row.get("duration_ms"),
        }
    }
